  const tf = [
    {s:17, st:"Vaskuläre Malformationen zeigen eine Endothelzellproliferation und regredieren meist spontan.", c:false, e:"Falsch - Malformationen sind strukturelle Fehlbildungen ohne Endothelproliferation, die weder wachsen (ausser proportional) noch regredieren; das trifft auf vaskuläre Tumoren wie das infantile Hämangiom zu."},
    {s:17, st:"GLUT1 ist beim infantilen Hämangiom positiv, beim NICH dagegen negativ.", c:true, e:"Korrekt - GLUT1 (und Ki-67 in der Proliferation) charakterisiert das IH; kongenitale Hämangiome (RICH/NICH/PICH) und Malformationen sind GLUT1-negativ."},
    {s:17, st:"Etwa die Hälfte der infantilen Hämangiome zeigt postnatal eine stabile Vorläuferläsion.", c:true, e:"Korrekt - nach einer Latenz von 1 bis 3 Wochen finden sich in ca. 50% Vorläufer wie Teleangiektasien mit vasokonstriktivem Halo, blasse Areale, rosa Makulae oder hämatomartige Flecken."},
    {s:17, st:"Tiefe und segmentale infantile Hämangiome können bis zum 9. bis 12. Lebensmonat proliferieren.", c:true, e:"Korrekt - der grösste Wachstumsschub liegt in den ersten 3 Monaten, tiefe und segmentale IH wachsen aber bis 9 bis 12, selten bis 24 Monate."},
    {s:17, st:"Ein periokuläres infantiles Hämangiom kann über Astigmatismus und Strabismus zu einer persistierenden Amblyopie führen.", c:true, e:"Korrekt - periokuläre IH sind eine funktionelle Indikation für eine frühe Propranolol-Therapie."},
    {s:17, st:"Timolol-Gel ist bei grossen segmentalen infantilen Hämangiomen die Therapie der ersten Wahl.", c:false, e:"Falsch - topisches Timolol eignet sich nur für kleine superfizielle IH an risikoarmer Lokalisation; segmentale, tiefe oder komplizierte IH werden mit Propranolol p.o. behandelt."},
    {s:17, st:"Die Propranolol-Therapie muss bei einer Bronchitis pausiert werden.", c:true, e:"Korrekt - wegen Bronchospasmus-Risiko wird Propranolol bei Bronchitis pausiert; Asthma/Bronchospasmus sind Kontraindikationen."},
    {s:17, st:"Kongenitale Hämangiome (RICH/NICH) sprechen gut auf Propranolol oder Timolol an.", c:false, e:"Falsch - Betablocker sind bei kongenitalen Hämangiomen wirkungslos; Optionen sind Exzision oder Pulsed-dye-Laser."},
    {s:17, st:"Der nuchale Naevus simplex (Storchenbiss) persistiert häufig lebenslang.", c:true, e:"Korrekt - im Gesicht bildet sich der Naevus simplex meist bis zum 1. bis 3. Lebensjahr zurück, im Nacken persistiert er oft."},
    {s:17, st:"Beim Sturge-Weber-Syndrom folgt der Naevus flammeus der Innervation der Trigeminusäste.", c:false, e:"Falsch - der Naevus flammeus entsteht entlang der embryonalen Plakode und hat embryologisch nichts mit dem N. trigeminus zu tun, auch wenn die V1-Region (Stirn, Glabella, Oberlid) die Risikolokalisation ist."},
    {s:17, st:"Ein kongenitales Glaukom beim Sturge-Weber-Syndrom ist ein ophthalmologischer Notfall.", c:true, e:"Korrekt - neben Glaukom drohen choroidale Blutung und Netzhautablösung; ophthalmologische Untersuchung bei Stirn-, Oberlid- oder V1-Beteiligung."},
    {s:17, st:"Das Klippel-Trénaunay-Syndrom ist eine High-flow-Läsion.", c:false, e:"Falsch - KTS ist eine kapillär-venös(-lymphatische) Slow-flow-Malformation (PIK3CA); die High-flow-Variante mit AV-Fisteln ist das Parkes-Weber-Syndrom (RASA1/EPHB4)."},
    {s:17, st:"Glomuvenöse Malformationen sind weich, komprimierbar und füllen sich bei Tieflagerung.", c:false, e:"Falsch - GVM sind druckschmerzhaft, nicht komprimierbar und pflastersteinartig; weich und kompressibel sind die klassischen venösen Malformationen."},
    {s:17, st:"Das Kasabach-Merritt-Phänomen wird typischerweise durch ein gewöhnliches infantiles Hämangiom ausgelöst.", c:false, e:"Falsch - Auslöser sind das kaposiforme Hämangioendotheliom und das büschelartige Hämangiom (tufted angioma), nicht das IH."},
    {s:17, st:"Eine Biopsie chronischer, nicht heilender Ulzera sollte aus dem Ulkusrand und nicht aus der Mitte entnommen werden.", c:true, e:"Korrekt - zur Abklärung eines Karzinoms oder einer anderen Grunderkrankung wird im Randbereich biopsiert."},
    {s:17, st:"Beim Ulcus cruris venosum sind Farbstoffe, Gerbstoffe und Antiseptika Mittel der ersten Wahl.", c:false, e:"Falsch - sie sind meist obsolet (verzögerte Wundheilung, Austrocknung, Kontaktsensibilisierung); Basis sind Kompression und stadiengerechte feuchte Wundauflagen."},
    {s:17, st:"Eine Unterdrucktherapie (VAC) ist beim arteriellen Ulkus ungünstig, beim Martorell-Ulkus aber Teil der Behandlung.", c:true, e:"Korrekt - beim arteriellen Ulkus verschlechtert VAC den Befund; beim mittel- bis grossflächigen Martorell-Ulkus folgt auf das Débridement bis zur Faszie ein NPWT-Verband mit zweizeitiger Spalthaut."},
    {s:17, st:"Betablocker sind beim Martorell-Ulkus die bevorzugten Antihypertensiva.", c:false, e:"Falsch - die Blutdruckeinstellung erfolgt mit ACE-Hemmern und Kalziumantagonisten, keine Betablocker; Vitamin-K-Antagonisten möglichst stoppen."},
    {s:17, st:"Die Livedo reticularis verschwindet bei Erwärmung, die Livedo racemosa nicht.", c:true, e:"Korrekt - die Livedo reticularis (Cutis marmorata) ist eine reversible funktionelle Störung; die Livedo racemosa persistiert temperaturunabhängig und ist pathologisch."},
    {s:17, st:"Beim Sneddon-Syndrom sind immer Antiphospholipid-Antikörper nachweisbar.", c:false, e:"Falsch - das Sneddon-Syndrom (Livedo racemosa plus zerebrale Ischämien) kann mit oder ohne Antiphospholipid-Antikörper auftreten."},
    {s:17, st:"In tropischen Ländern mit niedrigem Einkommen ist die Filariose die häufigste Ursache eines Lymphödems.", c:true, e:"Korrekt - die Infektion der Lymphgefässe mit Wuchereria bancrofti betrifft meist ein Bein."},
    {s:17, st:"Bei der Erythromelalgie lindert Wärme die Beschwerden.", c:false, e:"Falsch - Wärme ist der typische Trigger, Kühlung und Hochlagern lindern; das unterscheidet sie u.a. vom CRPS."},
    {s:17, st:"Bier-Spots lassen sich durch Herabhängenlassen der Extremität oder einen Tourniquet provozieren.", c:true, e:"Korrekt - venöse Stauung provoziert die weissen Makulae auf erythematös-zyanotischem Grund; mit akraler Zyanose, urtikariaähnlicher Eruption und orthostatischer Intoleranz als BASCULE-Syndrom."}
  ];
